api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.dm-sidebar {
width: 100%;
height: calc(100vh - 64px);
/* ✅ Fixed missing semicolons and removed margin-top that was breaking the layout */
background:linear-gradient(135deg, #3D3180, #5443AD, #6B5FBF);
border-right: 1px solid #e5e7eb;
padding: 24px 16px;
display: flex;
flex-direction: column;
font-family: "Inter", sans-serif;
position: sticky;
top: 64px;
box-sizing: border-box;
margin-top:13%
}



/* ===============================
   LOGO SECTION
=============================== */

.dm-logo {
    display: flex;
    align-items: center;
    margin-bottom: 30px;
    cursor: pointer;
}

.dm-logo-icon {
    width: 38px;
    height: 38px;
    background: rgba(255, 255, 255, 0.2);
    color: white;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-right: 10px;
    font-size: 16px;
}

.dm-title {
    font-weight: 600;
    font-size: 14px;
    color: #ffffff;
}

.dm-sub {
    font-size: 12px;
    color: rgba(255, 255, 255, 0.7);
}


/* ===============================
   MENU
=============================== */

.dm-menu {
    list-style: none;
    padding: 0;
    margin: 0;
    flex: 1;
}

.dm-menu li {
    margin-bottom: 6px;
}

/* ✅ White text on dark gradient bg */
.dm-menu a {
    display: flex;
    align-items: center;
    padding: 10px 14px;
    border-radius: 8px;
    text-decoration: none;
    font-size: 14px;
    color: #ffffff;
    transition: background 0.2s ease, color 0.2s ease;
}

.dm-menu a span {
    font-weight: 500;
}

/* ✅ White icons — gradient clip removed since sidebar bg is dark */
.dm-menu a i {
    width: 24px;
    text-align: center;
    margin-right: 12px;
    font-size: 15px;
    transition: all 0.2s ease;
    background: none;
    -webkit-background-clip: unset;
    -webkit-text-fill-color: #ffffff;
    background-clip: unset;
    color: #ffffff;
}


/* ===============================
   HOVER
=============================== */

/* ✅ Soft white overlay on hover instead of gray */
.dm-menu li:not(.active) a:hover {
    background: rgba(255, 255, 255, 0.15);
    color: #ffffff;
}

.dm-menu li:not(.active) a:hover i {
    background: none;
    -webkit-background-clip: unset;
    -webkit-text-fill-color: #ffffff;
    background-clip: unset;
    color: #ffffff;
}


/* ===============================
   ACTIVE LINK
=============================== */

/* ✅ Semi-transparent white pill for active item */
.dm-menu li.active a {
    background: rgba(255, 255, 255, 0.25);
    color: #ffffff;
}

.dm-menu li.active a i {
    background: none;
    -webkit-background-clip: unset;
    -webkit-text-fill-color: #ffffff;
    background-clip: unset;
    color: #ffffff;
}


/* ===============================
   FOOTER
=============================== */

.dm-footer {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.6);
    padding-top: 15px;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
}

.dm-version {
    margin-top: 3px;
}
